import { test, expect } from '@playwright/test';

test.describe('Table Row Selection with Header Checkbox', () => {
  test.beforeEach(async ({ page }) => {
    await page.goto('/table-list');
  });

  test('should select all rows when header checkbox is checked', async ({ page }) => {
    // Verify table is visible
    const table = page.getByRole('table');
    await expect(table).toBeVisible();

    // Verify header checkbox exists and is unchecked
    const headerCheckbox = page.getByRole('checkbox', { name: /select all/i });
    await expect(headerCheckbox).not.toBeChecked();

    // Verify row checkboxes exist and are unchecked
    const rowCheckboxes = page.locator('[data-testid="row-checkbox"]');
    const rowCount = await rowCheckboxes.count();
    expect(rowCount).toBeGreaterThan(0);

    // Verify row checkboxes are unchecked
    for (let i = 0; i < rowCount; i++) {
      const checkbox = rowCheckboxes.nth(i);
      await expect(checkbox).not.toBeChecked();
    }

    // Check the header checkbox
    await headerCheckbox.click();
    await expect(headerCheckbox).toBeChecked();

    // Verify all row checkboxes are now checked
    for (let i = 0; i < rowCount; i++) {
      const checkbox = rowCheckboxes.nth(i);
      await expect(checkbox).toBeChecked();
    }

    // Verify selection count is updated
    const selectionCount = page.getByText(/selected/i);
    await expect(selectionCount).toContainText('All');
  });

  test('should unselect all rows when header checkbox is unchecked', async ({ page }) => {
    // Check the header checkbox to select all rows
    const headerCheckbox = page.getByRole('checkbox', { name: /select all/i });
    await headerCheckbox.click();
    await expect(headerCheckbox).toBeChecked();

    // Verify all row checkboxes are checked
    const rowCheckboxes = page.locator('[data-testid="row-checkbox"]');
    const rowCount = await rowCheckboxes.count();
    for (let i = 0; i < rowCount; i++) {
      const checkbox = rowCheckboxes.nth(i);
      await expect(checkbox).toBeChecked();
    }

    // Uncheck the header checkbox
    await headerCheckbox.click();
    await expect(headerCheckbox).not.toBeChecked();

    // Verify all row checkboxes are now unchecked
    for (let i = 0; i < rowCount; i++) {
      const checkbox = rowCheckboxes.nth(i);
      await expect(checkbox).not.toBeChecked();
    }

    // Verify selection count is reset
    const selectionCount = page.getByText(/selected/i);
    await expect(selectionCount).toContainText('0');
  });
});
